                if(rawRegs.vals[170]==1){P7_System_Ext.acquisitionState.txt="数据采集：待机";}
                if(rawRegs.vals[170]==2){P7_System_Ext.acquisitionState.txt="数据采集：采集";}
                if(rawRegs.vals[170]==3){P7_System_Ext.acquisitionState.txt="数据采集：故障";}
            }
            if((rawRegs.vals[194] & 248)!=0){P7_System_Ext.extensionFault.txt="扩展故障位图："+intToString(rawRegs.vals[171]);}
        }
        // 摄像与通信位于索引4，不借用外围区的新鲜度。
        if(rawRegs.vals[179]==1){
            if((rawRegs.vals[194] & 256)!=0){
                if(rawRegs.vals[176]==0){P7_System_Ext.cameraState.txt="摄像状态：未接入";}
                if(rawRegs.vals[176]==1){P7_System_Ext.cameraState.txt="摄像状态：待机";}
                if(rawRegs.vals[176]==2){P7_System_Ext.cameraState.txt="摄像状态：摄像";}
                if(rawRegs.vals[176]==3){P7_System_Ext.cameraState.txt="摄像状态：故障";}
            }
            if((rawRegs.vals[194] & 512)!=0){
                if(rawRegs.vals[177]==0){P7_System_Ext.storageState.txt="存储状态：未接入";}
                if(rawRegs.vals[177]==1){P7_System_Ext.storageState.txt="存储状态：正常";}
                if(rawRegs.vals[177]==2){P7_System_Ext.storageState.txt="存储状态：空间不足";}
                if(rawRegs.vals[177]==3){P7_System_Ext.storageState.txt="存储状态：故障";}
            }
            if((rawRegs.vals[194] & 1024)!=0){
                if(rawRegs.vals[178]==0){P7_System_Ext.extensionComm.txt="扩展通信：未接入";}
                if(rawRegs.vals[178]==1){P7_System_Ext.extensionComm.txt="扩展通信：在线";}
                if(rawRegs.vals[178]==2){P7_System_Ext.extensionComm.txt="扩展通信：离线";}
                if(rawRegs.vals[178]==3){P7_System_Ext.extensionComm.txt="扩展通信：异常";}
            }
        }
    }
}
