if(formalProtocol==1 && regionValid.vals[4]==1 && regionBadRun.vals[4]<10 && rawRegs.vals[192]==21065 && rawRegs.vals[193]==1 && rawRegs.vals[194]!=65535){
        if((rawRegs.vals[194] & 4)==0){
            P5_Alarm.alarmLevel.txt="告警等级：未配置";
            P5_Alarm.alarmCode.txt="告警代码：未配置";
            P5_Alarm.alarmSource.txt="告警来源：未配置";
            P5_Alarm.alarmActive.txt="告警状态：未配置";
