                P5_Alarm.alarmExtra.txt="附加参数：无效";
                P5_Alarm.alarmFaultSummary.txt="故障摘要：无效";
            }
            if(regionValid.vals[3]==1 && regionBadRun.vals[3]<10 && rawRegs.vals[157]==1){
                if(rawRegs.vals[145]==0){P5_Alarm.alarmLevel.txt="告警等级：无";}
                if(rawRegs.vals[145]==1){P5_Alarm.alarmLevel.txt="告警等级：提示";}
