                if(rawRegs.vals[147]!=65535){P5_Alarm.alarmSource.txt="告警来源码："+intToString(rawRegs.vals[147]);}
                if(rawRegs.vals[147]==0){P5_Alarm.alarmSource.txt="告警来源：无";}
