                if(rawRegs.vals[148]==0){P5_Alarm.alarmActive.txt="告警状态：不活跃";}
                if(rawRegs.vals[148]==1){P5_Alarm.alarmActive.txt="告警状态：活跃";}
                if(rawRegs.vals[154]==0){P5_Alarm.alarmEmergency.txt="急停状态：未触发";}
                if(rawRegs.vals[154]==1){P5_Alarm.alarmEmergency.txt="急停状态：触发";}
                if(rawRegs.vals[155]==0){P5_Alarm.alarmStopResult.txt="停车结果：无请求";}
                if(rawRegs.vals[155]==1){P5_Alarm.alarmStopResult.txt="停车结果：停车中";}
                if(rawRegs.vals[155]==2){P5_Alarm.alarmStopResult.txt="停车结果：确认停止";}
                if(rawRegs.vals[155]==3){P5_Alarm.alarmStopResult.txt="停车结果：失败";}
                P5_Alarm.alarmSequence.txt="告警事件序号："+intToString(rawRegs.vals[144]);
                // 将U32毫秒拆成秒与余毫秒，全部中间值保持在S32范围。
                eventRemainder=rawRegs.vals[150]*536+rawRegs.vals[151];
                eventQuotient=eventRemainder/1000;
                eventSeconds=rawRegs.vals[150]*65+eventQuotient;
                eventRemainder=eventRemainder-eventQuotient*1000;
                P5_Alarm.alarmEventTime.txt="启动后："+intToString(eventSeconds)+" s "+intToString(eventRemainder)+" ms";
                positionValue=rawRegs.vals[152];
                if(positionValue>=32768){positionValue=positionValue-65536;}
                positionValue=positionValue*65536+rawRegs.vals[153];
                P5_Alarm.alarmExtra.txt="附加参数："+intToString(positionValue);
                P5_Alarm.alarmFaultSummary.txt="故障摘要位图："+intToString(rawRegs.vals[156]);
            }
