// 同步诊断在所有模式下显示，是否执行补偿仅影响补偿字段。
if(sys_pid==P6_Sync.id){
    P6_Sync.syncMacro.txt="同步宏：未知";
    P6_Sync.syncState.txt="同步状态：未知";
    P6_Sync.syncActualDiff.txt="实际速度差：未知";
    P6_Sync.syncEffectiveError.txt="有效误差：未知";
    P6_Sync.syncCompensation.txt="当前整数补偿：未知";
    P6_Sync.syncPairValid.txt="样本配对：未知";
    P6_Sync.syncRejectReason.txt="配对拒绝原因：未知";
    P6_Sync.syncSkew.txt="最近样本错时：未知";
    P6_Sync.syncAxis1Age.txt="轴1样本年龄：未知";
    P6_Sync.syncAxis2Age.txt="轴2样本年龄：未知";
if(formalProtocol==1 && regionValid.vals[4]==1 && regionBadRun.vals[4]<10 && rawRegs.vals[192]==21065 && rawRegs.vals[193]==1 && rawRegs.vals[194]!=65535){
        if((rawRegs.vals[194] & 2)==0){
            P6_Sync.syncMacro.txt="同步宏：未配置";
            P6_Sync.syncState.txt="同步状态：未配置";
            P6_Sync.syncActualDiff.txt="实际速度差：未配置";
            P6_Sync.syncEffectiveError.txt="有效误差：未配置";
            P6_Sync.syncCompensation.txt="当前整数补偿：未配置";
            P6_Sync.syncPairValid.txt="样本配对：未配置";
            P6_Sync.syncRejectReason.txt="配对拒绝原因：未配置";
