            P6_Sync.syncAxis1Age.txt="轴1样本年龄：未配置";
            P6_Sync.syncAxis2Age.txt="轴2样本年龄：未配置";
        }else{
            if(regionValid.vals[2]==1 && regionBadRun.vals[2]<10){
                if(rawRegs.vals[142]!=1){P6_Sync.syncState.txt="同步快照：无效";}
                if(rawRegs.vals[142]==1){
                    P6_Sync.syncActualDiff.txt="实际速度差：无效";
                    P6_Sync.syncEffectiveError.txt="有效误差：无效";
                    P6_Sync.syncCompensation.txt="当前整数补偿：无效";
                    if(rawRegs.vals[128]!=65535){P6_Sync.syncMacro.txt="同步控制位："+intToString(rawRegs.vals[128]);}
                    if(rawRegs.vals[129]==0){P6_Sync.syncState.txt="同步状态：关闭";}
                    if(rawRegs.vals[129]==1){P6_Sync.syncState.txt="同步状态：待配对";}
                    if(rawRegs.vals[129]==2){P6_Sync.syncState.txt="同步状态：激活";}
