                    if(rawRegs.vals[129]==4){P6_Sync.syncState.txt="同步状态：故障";}
                    if(rawRegs.vals[130]==0){P6_Sync.syncPairValid.txt="样本配对：无效";}
                    if(rawRegs.vals[130]==1){
                        P6_Sync.syncPairValid.txt="样本配对：有效";
                        if(rawRegs.vals[132]!=32767){
                            speedValue=rawRegs.vals[132];
                            if(speedValue>=32768){speedValue=speedValue-65536;}
                            P6_Sync.syncActualDiff.txt="实际速度差："+intToString(speedValue)+" rpm";
                        }
                        if(rawRegs.vals[133]!=32767){
                            speedValue=rawRegs.vals[133];
                            if(speedValue>=32768){speedValue=speedValue-65536;}
                            P6_Sync.syncEffectiveError.txt="有效误差："+intToString(speedValue)+" rpm";
                        }
                        // 只使用主控已经执行的补偿结果，运行补充也必须有效。
                        if(rawRegs.vals[128]!=65535 && (rawRegs.vals[128] & 2)!=0 && (rawRegs.vals[194] & 4096)!=0 && rawRegs.vals[207]==1 && rawRegs.vals[203]>=1 && rawRegs.vals[203]<=3 && rawRegs.vals[134]!=32767){
                            speedValue=rawRegs.vals[134];
                            if(speedValue>=32768){speedValue=speedValue-65536;}
                            P6_Sync.syncCompensation.txt="当前整数补偿："+intToString(speedValue)+" rpm";
                        }
                    }
                    // 即使尚未配对，也能知道本拍没有执行补偿。
                    if(rawRegs.vals[128]!=65535 && (rawRegs.vals[128] & 2)==0){
                        P6_Sync.syncCompensation.txt="当前整数补偿：未执行";
                        P6_Sync.syncEffectiveError.txt="有效误差：未执行";
                    }
                    if((rawRegs.vals[194] & 4096)!=0 && rawRegs.vals[207]==1 && (rawRegs.vals[203]==0 || rawRegs.vals[203]==4)){
                        P6_Sync.syncCompensation.txt="当前整数补偿：未执行";
